<original_code>
#include <bits/stdc++.h>
using namespace std;

#define mp make_pair
#define all(x) (x).begin(), (x).end()
#define sz(x) ((int)(x).size())
#define fi first
#define se second
typedef long long ll;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
const int N = 12, INF = 1000000009;
const int move_x[4] = {0, 1, 0, -1};
const int move_y[4] = {1, 0, -1, 0};

struct Coord {
    int r, c;
    Coord() {}
    Coord(int _r, int _c) : r(_r), c(_c) {}
};

int n, t;
char mapA[N][N], mapB[N][N];

int start_r, start_c;
int dist[N][N];

void run_bfs(int d[N][N], int sr, int sc) {
    bool visited[N][N] = {};
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            d[i][j] = INF;
    queue<Coord> q;
    visited[sr][sc] = true;
    d[sr][sc] = 0;
    q.push(Coord(sr, sc));
    while (!q.empty()) {
        Coord cur = q.front(); q.pop();
        for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
            Coord next_cell = cur;
            next_cell.r += move_x[dir_idx];
            next_cell.c += move_y[dir_idx];
            if (next_cell.r >= 0 && next_cell.r < n && next_cell.c >= 0 && next_cell.c < n
                && !visited[next_cell.r][next_cell.c]
                && mapA[next_cell.r][next_cell.c] >= '0'
                && mapA[next_cell.r][next_cell.c] <= '9') {
                visited[next_cell.r][next_cell.c] = true;
                d[next_cell.r][next_cell.c] = d[cur.r][cur.c] + 1;
                q.push(next_cell);
            }
        }
    }
}

bool residuals[N * 6][N][N][N][N];
bool reach[N][N][N][N];

int graph[2 * N * N][2 * N * N];

int parent[2 * N * N];
bool visited_nodes[2 * N * N];

bool flow_search() {
    memset(visited_nodes, false, sizeof(visited_nodes));
    memset(parent, 0, sizeof(parent));
    queue<int> q;
    visited_nodes[0] = true;
    q.push(0);
    while (!q.empty()) {
        int node = q.front(); q.pop();
        if (node == 2 * n * n + 1)
            return true;
        for (int h = 0; h <= 2 * n * n + 1; ++h) {
            if (graph[node][h]) {
                if (!visited_nodes[h]) {
                    visited_nodes[h] = true;
                    parent[h] = node;
                    q.push(h);
                }
            }
        }
    }
    return false;
}

void process_input() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i)
        scanf(" %s", mapA[i]);
    for (int i = 0; i < n; ++i)
        scanf(" %s", mapB[i]);
    scanf("%d%d", &start_r, &start_c);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (mapA[i][j] == 'Z') {
                start_r = i; start_c = j;
            }
    run_bfs(dist, start_r, start_c);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if ('0' <= mapA[i][j] && mapA[i][j] <= '9')
                residuals[0][i][j][i][j] = true;
    for (int step = 0; step < t; ++step) {
        for (int sx = 0; sx < n; ++sx)
            for (int sy = 0; sy < n; ++sy)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y) {
                        if (!residuals[step][sx][sy][x][y]) continue;
                        if (dist[x][y] <= step) continue;
                        for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
                            int hx = x + move_x[dir_idx];
                            int hy = y + move_y[dir_idx];
                            if (hx >= 0 && hx < n && hy >= 0 && hy < n && '0' <= mapA[hx][hy] && mapA[hx][hy] <= '9') {
                                if (dist[hx][hy] >= step + 1)
                                    residuals[step + 1][sx][sy][hx][hy] = true;
                            }
                        }
                    }
    }
    for (int step = 0; step <= t; ++step)
        for (int sx = 0; sx < n; ++sx)
            for (int sy = 0; sy < n; ++sy)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (residuals[step][sx][sy][x][y])
                            reach[sx][sy][x][y] = true;

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            if ('0' <= mapA[x1][y1] && mapA[x1][y1] <= '9')
                graph[0][x1 * n + y1 + 1] = mapA[x1][y1] - '0';

    for (int x2 = 0; x2 < n; ++x2)
        for (int y2 = 0; y2 < n; ++y2)
            if ('0' <= mapB[x2][y2] && mapB[x2][y2] <= '9')
                graph[n * n + x2 * n + y2 + 1][2 * n * n + 1] = mapB[x2][y2] - '0';

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            for (int x2 = 0; x2 < n; ++x2)
                for (int y2 = 0; y2 < n; ++y2) {
                    if (!('0' <= mapA[x1][y1] && mapA[x1][y1] <= '9')) continue;
                    if (!('0' <= mapA[x2][y2] && mapA[x2][y2] <= '9')) continue;
                    if (!reach[x1][y1][x2][y2]) continue;
                    graph[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;
                }

    while (flow_search()) {
        int min_flow = INF;
        for (int i = 2 * n * n + 1; i; i = parent[i]) {
            min_flow = min(min_flow, graph[parent[i]][i]);
        }
        for (int i = 2 * n * n + 1; i; i = parent[i]) {
            graph[parent[i]][i] -= min_flow;
            graph[i][parent[i]] += min_flow;
        }
    }

    int total = 0;
    for (int i = 0; i <= 2 * n * n + 1; ++i)
        total += graph[i][0];

    printf("%d\n", total);
}

int main() {
    #ifdef SOMETHING
    freopen("input.txt", "r", stdin);
    #endif
    process_input();
    return 0;
}
